"""Курируемые группы утверждений (написаны и просмотрены автором).

Каждая группа: верные и неверные утверждения одной темы, термы для вопроса «сколько»
и карточка открытого ответа с ключевыми пунктами. Группы разных тем независимы:
семейство корпуса = группа; проверочные группы в обучение не попадают.
"""
from .core import about, multiple, numeric, open_task, pick_distinct, plural, single, topic_brief

G = []


def group(skill, spec, topic, stem, correct, wrong, terms=None, term_q=None, open_q=None, points=None, grades=('junior', 'middle')):
    G.append(dict(skill=skill, spec=spec, topic=topic, stem=stem, correct=correct, wrong=wrong,
                  terms=terms, term_q=term_q, open_q=open_q, points=points, grades=grades))


