def facts_family(rng, grade, g):
    """Один сценарий из группы утверждений -> задания четырёх типов."""
    skills, spec = [g['skill']], g['spec']
    topic = g['topic']
    out = {}
    n_right = rng.randint(2, 3)
    brief_kw = lambda kind: topic_brief(rng, kind, spec, grade, topic)
    right = rng.sample(g['correct'], n_right)
    wrong = rng.sample(g['wrong'], rng.randint(1, 2) if n_right == 3 else 2)
    out['multiple_choice'] = (multiple(rng, f'Верные утверждения {about(topic)}', f'Какие {g["stem"]} верны? Выберите все верные.', right, wrong, skills),
                              brief_kw('multiple_choice'))
    one = rng.choice(g['correct'])
    out['single_choice'] = (single(rng, f'Верное утверждение {about(topic)}', f'Какое из утверждений {about(topic)} верно?', one, rng.sample(g['wrong'], 3), skills),
                            brief_kw('single_choice'))
    if g['terms']:
        good, bad = g['terms']
        kg = rng.randint(1, min(len(good), 4))
        kb = rng.randint(1, min(len(bad), 5 - kg if kg < 5 else 1))
        items = rng.sample(good, kg) + rng.sample(bad, kb)
        rng.shuffle(items)
        out['numeric'] = (numeric(f'Подсчёт {about(topic)}', f'{g["term_q"]}: {", ".join(items)}?', kg, '', skills), brief_kw('numeric'))
    if g['points']:
        pts = g['points']
        k = len(pts)
        half = max(1, k // 2)
        out['open_response'] = (open_task(f'Объяснение {about(topic)}', g['open_q'],
                                          'ключевые пункты не названы либо содержат фактические ошибки',
                                          f'названы и объяснены не все пункты: {"; ".join(pts[:half])}, но не раскрыто остальное',
                                          '; '.join(pts), skills), brief_kw('open_response'))
    return {'spec': spec, 'skills': skills, 'tasks': out, 'work': '; '.join(g['correct'][:4])}


FAMILIES = [(lambda g: (lambda rng, grade: facts_family(rng, grade, g)))(g) for g in G]
FAMILY_NAMES = [f'facts_{g["skill"]}_{i}' for i, g in enumerate(G)]
